package com.vibeguard.samples.reviews; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*; import java.util.concurrent.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/products/{productId}/reviews") public class ReviewController {private final Map<String,Review> reviews=new ConcurrentHashMap<>();@PostMapping public ResponseEntity<Review> submit(@PathVariable String productId,@Valid @RequestBody Request request){String id=UUID.randomUUID().toString();Review review=new Review(id,productId,request.stars(),request.text());reviews.put(id,review);return ResponseEntity.status(201).body(review);}@GetMapping public List<Review> list(@PathVariable String productId){return reviews.values().stream().filter(r->r.productId().equals(productId)).toList();}@DeleteMapping("/{id}") public ResponseEntity<Void> remove(@PathVariable String productId,@PathVariable String id){reviews.remove(id);return ResponseEntity.noContent().build();}record Request(@Min(1) @Max(5) int stars,@NotBlank String text){}record Review(String id,String productId,int stars,String text){} }
